<div class="content-wrapper"><section class="content-header"><h1>Basic Data Area</h1></section><section class="content"><?php foreach(array('Berhasil'=>'success','Gagal'=>'danger') as $key=>$style):$message=$this->session->flashdata($key);if($message): ?><div class="alert alert-<?= $style ?>"><?= html_escape($message) ?></div><?php endif;endforeach; ?><?php if($error): ?><div class="alert alert-danger"><?= html_escape($error) ?></div><?php endif; ?><div class="box box-primary"><div class="box-body"><p>Area menjadi batas akses untuk kapal, perusahaan, DO, SPP, KSOP, tagihan, dan piutang. Pengelolaan area hanya untuk administrator.</p><form method="post"><?php $this->load->view('pipeline/billing_token'); ?><div class="row"><?php foreach(array('No_SPBB'=>'Kode Area / SPBB','Area'=>'Nama Area','Pic'=>'PIC','BunkerIssuerCode'=>'Kode Surat Area (mis. ASDP-PB)') as $k=>$label): ?><div class="col-sm-4 form-group"><label><?= $label ?></label><input class="form-control" name="<?= $k ?>" maxlength="<?= in_array($k,array('No_SPBB','BunkerIssuerCode'),true)?30:100 ?>" <?= !in_array($k,array('Pic','BunkerIssuerCode'),true)?'required':'' ?>></div><?php endforeach; ?></div><button class="btn btn-primary">Tambah Area</button></form></div></div><div class="box"><div class="box-body"><table class="table table-striped"><tr><th>ID Area</th><th>Nama Area</th><th>PIC</th><th>Kode Penerbit Surat Bunker</th></tr><?php foreach($branches as $b): ?><tr><td><?= (int)$b['SpbbID'] ?></td><td><?= html_escape($b['SpbbName']) ?></td><td><?= html_escape(isset($b['Pic'])?$b['Pic']:'') ?></td><td><form method="post" action="<?= site_url('Pipeline_setup/area_issuer_code/'.$b['SpbbID']) ?>"><?php $this->load->view('pipeline/billing_token'); ?><div style="display:flex;gap:6px;min-width:210px"><input name="BunkerIssuerCode" class="form-control" maxlength="30" placeholder="ASDP-PB" aria-label="Kode penerbit area" value="<?= html_escape(isset($b['BunkerIssuerCode'])?$b['BunkerIssuerCode']:'') ?>" required><button class="btn btn-default btn-sm">Simpan</button></div></form></td></tr><?php endforeach; ?></table></div></div></section></div>